from pathlib import Path
import re

def sub_once(path, pattern, replacement, flags=0):
    p=Path(path); text=p.read_text(); out,n=re.subn(pattern,replacement,text,count=1,flags=flags)
    if n!=1: raise SystemExit(f'{path}: expected one match, found {n}')
    p.write_text(out)

p='project-store.js'
replacement="""async function writeAllIndexed(projects){if(!Array.isArray(projects))throw new TypeError('Project storage payload must be an array.');const db=await openDatabase(),tx=db.transaction([PROJECTS,META],'readwrite'),store=tx.objectStore(PROJECTS),meta=tx.objectStore(META),seen=new Set(),plans=[],saved=[];try{for(const project of projects){const id=projectIdentity(project);if(!id)throw storageError('Every bulk-written project requires a JOB_ID.','PROJECT_ID_REQUIRED');if(seen.has(id))throw storageError(`Bulk project storage contains duplicate JOB_ID ${id}.`,'DUPLICATE_PROJECT_ID');seen.add(id);const prior=await request(store.get(id)),currentRevision=Number(prior?.revision||0),incomingRevision=Number(project?.revision||0);if(prior&&incomingRevision!==currentRevision)throw storageError(`Project revision conflict for ${id}: expected ${incomingRevision}, found ${currentRevision}.`,'STALE_PROJECT_REVISION');const next=clone(project);delete next.projectSha256;let digest=projectSha256(next);if(prior?.projectSha256===digest){next.revision=currentRevision;next.projectSha256=prior.projectSha256;saved.push(next);continue;}next.revision=prior?currentRevision+1:0;delete next.projectSha256;digest=projectSha256(next);plans.push({id,next,digest});saved.push(next);}fault('during-project-write');for(const plan of plans){store.put({jobId:plan.id,revision:plan.next.revision,project:plan.next,projectSha256:plan.digest,updatedAt:now()});meta.put({key:'selectedProject',value:plan.id,updatedAt:now()});meta.put({key:'lastCommittedRevision',value:{jobId:plan.id,revision:plan.next.revision,projectSha256:plan.digest},updatedAt:now()});}fault('before-transaction-commit');await complete(tx);for(const plan of plans){plan.next.projectSha256=plan.digest;try{new BroadcastChannel('closed-loop-reliability').postMessage({type:'PROJECT_CHANGED',jobId:plan.id,revision:plan.next.revision});}catch{}}return saved;}catch(error){try{tx.abort();}catch{}throw error;}}
function writeAll"""
sub_once(p,r"async function writeAllIndexed\(projects\)\{.*?return saved;\}\nfunction writeAll",replacement,re.S)

p='verify-browser-extra.mjs'
sub_once(p,r"  assert\(staleAttempt\?\.accepted===false&&staleAttempt\.code==='STALE_PROJECT_REVISION','Second-tab stale project revision was accepted\.'\);tab2\.close\(\);","  assert(staleAttempt?.accepted===false&&staleAttempt.code==='STALE_PROJECT_REVISION','Second-tab stale project revision was accepted.');\n  const bulkAtomic=await evalValue(cdp,`(async()=>{const store=closedLoopProjectStore,all=await store.readAll(),stale=${JSON.stringify(starting.project)},other=all.find(x=>x.job?.JOB_ID!==${JSON.stringify(sharedJob)});if(!other)return {skipped:true};const otherId=other.job.JOB_ID,otherRevision=other.revision,otherTitle=other.job.JOB_TITLE,sharedTitle=all.find(x=>x.job?.JOB_ID===${JSON.stringify(sharedJob)})?.job?.JOB_TITLE;other.job.JOB_TITLE='MUST NOT COMMIT';stale.job.JOB_TITLE='MUST NOT COMMIT STALE';let code='';try{await store.writeAll([other,stale]);}catch(e){code=e.code||'';}const after=await store.readAll(),afterOther=after.find(x=>x.job?.JOB_ID===otherId),afterShared=after.find(x=>x.job?.JOB_ID===${JSON.stringify(sharedJob)});return {code,otherRevisionSame:afterOther?.revision===otherRevision,otherTitleSame:afterOther?.job?.JOB_TITLE===otherTitle,sharedTitleSame:afterShared?.job?.JOB_TITLE===sharedTitle};})()`);\n  assert(!bulkAtomic?.skipped&&bulkAtomic.code==='STALE_PROJECT_REVISION'&&bulkAtomic.otherRevisionSame&&bulkAtomic.otherTitleSame&&bulkAtomic.sharedTitleSame,'Bulk project persistence did not reject stale input atomically.');\n  const duplicateBulk=await evalValue(cdp,`(async()=>{const store=closedLoopProjectStore,p=(await store.readAll())[0];try{await store.writeAll([p,p]);return {accepted:true};}catch(e){return {accepted:false,code:e.code||''};}})()`);assert(duplicateBulk?.accepted===false&&duplicateBulk.code==='DUPLICATE_PROJECT_ID','Bulk storage accepted duplicate project identities.');tab2.close();")

p=Path('index.html'); text=p.read_text(); out,n=re.subn(r'([A-Za-z0-9.-]+\.js)\?v=[A-Za-z0-9._-]+',r'\1?v=20260826-atomic-storage',text)
if n!=8: raise SystemExit(f'index.html: expected 8 runtime script tokens, found {n}')
